// Generated by /ship coverage audit
// Value: protects=the eval judge scores only a reply from its own model that finished and parses to a valid verdict, and bills every rejection;
//   fails_when=a wrong served model, a max_tokens cut or a malformed verdict is accepted, or a rejection drops the billed usage and model;
//   why_new=judge() and its verdict guards had no test, so a bad judge reply could be scored or its cost missed in the errors sidecar;
//   seam=none;
//   no_claim=green does not prove the real judge model follows the prompt or returns JSON the guards accept.
import { describe, expect, test } from "bun:test";
import {
  JUDGE_MODEL,
  judge,
  type ChatCall,
  type JudgeVerdict,
} from "../../../../../../scripts/evals/translation/judge";

const USAGE = { input_tokens: 1200, output_tokens: 3400 };

// The real reply also carries excerpts, which the guards ignore.
const VERDICT = {
  errors: [
    {
      category: "mistranslation",
      severity: "major",
      source_excerpt: "bank",
      translation_excerpt: "Bank",
      explanation: "Riverbank rendered as a financial bank.",
    },
    { category: "fluency", severity: "minor", explanation: "Slightly awkward phrasing." },
  ],
  score: 72,
  rationale: "Mostly accurate with one meaning error.",
} as JudgeVerdict;

type Reply = Awaited<ReturnType<ChatCall>>;

/** Chat stand-in that records each request and answers with the given reply fields. */
function fakeChat(reply: Partial<Reply> = {}) {
  const calls: Parameters<ChatCall>[0][] = [];
  const chat: ChatCall = async (body) => {
    calls.push(body);
    return {
      model: JUDGE_MODEL,
      text: JSON.stringify(VERDICT),
      finish_reason: "stop",
      usage: USAGE,
      ...reply,
    };
  };
  return { chat, calls };
}

type JudgeFailure = Error & { judge_model?: string; judge_usage?: unknown };

async function rejection(promise: Promise<unknown>): Promise<JudgeFailure> {
  try {
    await promise;
  } catch (error) {
    return error as JudgeFailure;
  }
  throw new Error("expected judge() to reject");
}

describe("judge", () => {
  test("returns the parsed verdict with the judge model and usage", async () => {
    const { chat } = fakeChat();

    const result = await judge(chat, "German (de)", "Hello", "Hallo");

    expect(result).toEqual({ verdict: VERDICT, model: JUDGE_MODEL, usage: USAGE });
  });

  test("asks its own model for a JSON reply with the source and translation as tagged data", async () => {
    const { chat, calls } = fakeChat();

    await judge(chat, "German (de)", "Hello world", "Hallo Welt");

    expect(calls).toHaveLength(1);
    expect(calls[0]).toMatchObject({
      model: JUDGE_MODEL,
      response_format: { type: "json_object" },
    });
    const user = calls[0]?.messages.find((message) => message.role === "user")?.content;
    expect(user).toContain("Target language: German (de)");
    expect(user).toContain("<source>\nHello world\n</source>");
    expect(user).toContain("<translation>\nHallo Welt\n</translation>");
  });

  test("extracts the verdict object from a reply wrapped in prose or a code fence", async () => {
    const wrapped = `Here is my review:\n\`\`\`json\n${JSON.stringify(VERDICT)}\n\`\`\`\nDone.`;
    const { chat } = fakeChat({ text: wrapped });

    const { verdict } = await judge(chat, "German (de)", "Hello", "Hallo");

    expect(verdict).toEqual(VERDICT);
  });

  test("accepts a verdict with no errors", async () => {
    const perfect = { errors: [], score: 100, rationale: "Flawless." };
    const { chat } = fakeChat({ text: JSON.stringify(perfect) });

    const { verdict } = await judge(chat, "German (de)", "Hello", "Hallo");

    expect(verdict).toEqual(perfect);
  });
});

describe("judge rejections carry the billed usage", () => {
  test("rejects a reply served by a different model", async () => {
    const { chat } = fakeChat({ model: "@cf/openai/gpt-oss-120b" });

    const error = await rejection(judge(chat, "German (de)", "Hello", "Hallo"));

    expect(error.message).toBe("judge served by @cf/openai/gpt-oss-120b");
    expect(error.judge_model).toBe("@cf/openai/gpt-oss-120b");
    expect(error.judge_usage).toEqual(USAGE);
  });

  test("rejects a reply cut off at max_tokens even when the text parses as a verdict", async () => {
    const { chat } = fakeChat({ finish_reason: "length" });

    const error = await rejection(judge(chat, "German (de)", "Hello", "Hallo"));

    expect(error.message).toBe("judge hit max_tokens");
    expect(error.judge_model).toBe(JUDGE_MODEL);
    expect(error.judge_usage).toEqual(USAGE);
  });

  test("checks the served model before the finish reason", async () => {
    const { chat } = fakeChat({ model: "@cf/openai/gpt-oss-120b", finish_reason: "length" });

    const error = await rejection(judge(chat, "German (de)", "Hello", "Hallo"));

    expect(error.message).toBe("judge served by @cf/openai/gpt-oss-120b");
  });

  const invalid: Record<string, string> = {
    "plain text": "I think this translation is good.",
    "an empty reply": "",
    "truncated JSON": '{"errors": [], "score": 80, "rationale": "cut',
    "a missing score": JSON.stringify({ errors: [], rationale: "ok" }),
    "a string score": JSON.stringify({ errors: [], score: "90", rationale: "ok" }),
    "an infinite score": '{"errors": [], "score": 1e999, "rationale": "ok"}',
    "a missing rationale": JSON.stringify({ errors: [], score: 90 }),
    "errors that are not an array": JSON.stringify({ errors: {}, score: 90, rationale: "ok" }),
    "an unknown error category": JSON.stringify({
      errors: [{ category: "style", severity: "minor", explanation: "x" }],
      score: 90,
      rationale: "ok",
    }),
    "an unknown severity": JSON.stringify({
      errors: [{ category: "grammar", severity: "fatal", explanation: "x" }],
      score: 90,
      rationale: "ok",
    }),
    "an error without an explanation": JSON.stringify({
      errors: [{ category: "grammar", severity: "minor" }],
      score: 90,
      rationale: "ok",
    }),
    "a null error entry": JSON.stringify({ errors: [null], score: 90, rationale: "ok" }),
  };

  test.each(Object.entries(invalid))("rejects %s as no valid verdict", async (_name, text) => {
    const { chat } = fakeChat({ text });

    const error = await rejection(judge(chat, "German (de)", "Hello", "Hallo"));

    expect(error.message).toBe("judge returned no valid verdict");
    expect(error.judge_model).toBe(JUDGE_MODEL);
    expect(error.judge_usage).toEqual(USAGE);
  });
});
